import importlib.util
import os
import unittest

def student_file():
    """PythonGrader uses student.py; Udemy coding exercises use exercise.py."""
    for name in ('student.py', 'exercise.py'):
        if os.path.isfile(name):
            return name
    return 'student.py'


def load_student():
    path = student_file()
    spec = importlib.util.spec_from_file_location("_student_under_test", path)
    if spec is None or spec.loader is None:
        raise RuntimeError("Could not load student file: " + path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


class FunctionTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.mod = load_student()
        if not hasattr(cls.mod, "computepay"):
            raise AssertionError("Define a function named computepay(h, r).")

    def test_overtime(self):
        got = self.mod.computepay(45, 10.5)
        self.assertAlmostEqual(got, 498.75, places=4,
            msg="Pay 40 hours at the normal rate and the remaining hours at 1.5x.")
    def test_no_overtime(self):
        got = self.mod.computepay(40, 10)
        self.assertAlmostEqual(got, 400.0, places=4,
            msg="When hours are 40 or less, return hours * rate.")


class SourceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open(student_file(), encoding='utf-8') as f:
            cls.src = f.read()

    def test_source_def(self):
        self.assertIn("def", self.src,
            "You must define a function called computepay.")

    def test_source_computepay(self):
        self.assertIn("computepay", self.src,
            "You must use a function called computepay to do the computation.")

    def test_source_return(self):
        self.assertIn("return", self.src,
            "You must use a return statement to return the computed pay.")

    def test_source_if(self):
        self.assertIn("if", self.src,
            "You should use an if statement to decide the overtime computation or not.")

    def test_source_not_input(self):
        self.assertNotIn("input", self.src,
            "Do not prompt for input \u2014 only write the computepay function.")

    def test_source_not_print(self):
        self.assertNotIn("print", self.src,
            "Do not print \u2014 return the pay from computepay.")

    def test_source_not_sum(self):
        self.assertNotIn("sum(", self.src,
            "Do not use a variable named sum or a function named sum()")

    def test_source_not_498(self):
        self.assertNotIn("498", self.src,
            "You must actually calculate the pay.")
